//! 🧪️ Real original publication preserves source identity, bounded copies, physical receipts and terminal custody.
use super::*;
fn observed<T>(body:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(body);(value,(heap.requested_bytes,heap.released_bytes))}
fn original_grant()->RetainedCloneGrant{let law:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let p=law["originalGrant"].as_array().unwrap();RetainedCloneGrant{maximum_items:p[0].as_u64().unwrap()as usize,maximum_copy_bytes:p[1].as_u64().unwrap()as usize,maximum_capacity_bytes:p[2].as_u64().unwrap()as usize,maximum_release_bytes:p[3].as_u64().unwrap()as usize,maximum_depth:p[4].as_u64().unwrap()as usize}}
fn assert_physical(progress:RetainedCloneProgress,heap:(usize,usize),grant:RetainedCloneGrant){assert!(progress.fits(grant));assert_eq!((progress.retained_capacity_bytes,progress.released_bytes),heap)}
#[test]
fn original_source_publication_preserves_native_identity_paid_stages_and_every_cancellation_frontier(){
 let grant=original_grant();let source:[u8;8193]=std::array::from_fn(|index|(index%251)as u8);let foreign=source;let operation=OperationId(99731);let generation=Generation(5);
 for extent in [0,3,20,321,8193]{for kind in [JobPublicationKind::Preview,JobPublicationKind::Checkpoint{applied_progress:7},JobPublicationKind::Fault]{for cut in [0,1,3,257,usize::MAX]{
  let source=&source[..extent];let((cancel,cancel_birth),heap)=observed(||CancelToken::admit_root(grant).unwrap().unwrap());assert_physical(cancel_birth,heap,grant);let mut born=heap.0;let mut released=heap.1;
  let((mut authority,authority_birth),heap)=observed(||JobPayloadAuthority::admit(operation,generation,grant).unwrap().unwrap());assert_physical(authority_birth,heap,grant);born+=heap.0;released+=heap.1;
  let(mut publication,heap)=observed(RetainedJobPublication::new);assert_eq!(heap,(0,0));let native_owner=std::ptr::addr_of!(publication);let source_pointer=source.as_ptr();let mut sequence=0;let mut turns=0;let mut copied=0;let mut descriptor=None;
  while turns<cut&&descriptor.is_none(){
   let mut receipt=Default::default();let cx=StepContext::with_payload_authority(operation,generation,StepBudget::new(1,u64::MAX,grant),&cancel,logical_now_us,&mut sequence,&mut receipt,&authority).unwrap();let(demand,heap)=observed(||publication.advance_demands(kind,source,&cx).unwrap());assert_eq!(heap,(0,0));drop(cx);
   for denied in [Some(RetainedCloneGrant{maximum_items:0,..grant}),(demand.copy_bytes>0).then_some(RetainedCloneGrant{maximum_copy_bytes:demand.copy_bytes.saturating_sub(1),..grant}),(demand.capacity_bytes>0).then_some(RetainedCloneGrant{maximum_capacity_bytes:0,..grant}),(demand.depth>0).then_some(RetainedCloneGrant{maximum_depth:demand.depth.saturating_sub(1),..grant})].into_iter().flatten(){
    let mut receipt=Default::default();let mut cx=StepContext::with_payload_authority(operation,generation,StepBudget::new(1,u64::MAX,denied),&cancel,logical_now_us,&mut sequence,&mut receipt,&authority).unwrap();let(result,heap)=observed(||publication.advance_from_source(kind,source,&mut cx).unwrap().map(JobOutcomeBorrow::into_descriptor));assert!(result.is_none());assert_eq!(heap,(0,0));assert_eq!(cx.retained_progress(),Default::default());assert_eq!(std::ptr::addr_of!(publication),native_owner);assert_eq!(source.as_ptr(),source_pointer);
   }
   if publication.binding.is_some()&&extent>0{let mut receipt=Default::default();let mut cx=StepContext::with_payload_authority(operation,generation,StepBudget::new(1,u64::MAX,grant),&cancel,logical_now_us,&mut sequence,&mut receipt,&authority).unwrap();let(result,heap)=observed(||publication.advance_from_source(kind,&foreign[..extent],&mut cx).map(|result|result.map(JobOutcomeBorrow::into_descriptor)));assert!(result.is_err());assert_eq!(heap,(0,0));assert_eq!(cx.retained_progress(),Default::default());}
   let mut receipt=Default::default();let mut cx=StepContext::with_payload_authority(operation,generation,StepBudget::new(1,u64::MAX,grant),&cancel,logical_now_us,&mut sequence,&mut receipt,&authority).unwrap();let(result,heap)=observed(||publication.advance_from_source(kind,source,&mut cx).unwrap().map(JobOutcomeBorrow::into_descriptor));let progress=cx.retained_progress();assert_physical(progress,heap,grant);assert_eq!(progress.copied_items,1);copied+=progress.copied_bytes;born+=heap.0;released+=heap.1;descriptor=result;turns+=1;assert!(turns<2000);assert_eq!(source.as_ptr(),source_pointer);assert_eq!(std::ptr::addr_of!(publication),native_owner);
  }
  if let Some(mut descriptor)=descriptor{assert_eq!(copied,extent);let(view,heap)=observed(||publication.borrow_outcome(&descriptor).unwrap());assert_eq!(heap,(0,0));let payload=match view{JobOutcomeView::PreviewReady{payload,..}=>payload,JobOutcomeView::CheckpointReady{state,applied_progress,..}=>{assert_eq!(applied_progress,7);state},JobOutcomeView::Fault{detail,..}=>detail,_=>panic!("wrong original publication kind")};assert_eq!(payload.len(),extent);let pointer=payload as*const _;let mut offset=0;for index in 0..payload.page_count(){let page=payload.page(index).unwrap();assert_eq!(page,&source[offset..offset+page.len()]);offset+=page.len();}assert_eq!(offset,extent);assert_eq!(publication.published().unwrap()as*const _,pointer);let(step,heap)=observed(||descriptor.acknowledge(RetainedCloneGrant{maximum_items:0,..grant}));assert_eq!(heap,(0,0));assert_eq!(step.progress(),Default::default());assert!(!descriptor.is_acknowledged());let(step,heap)=observed(||descriptor.acknowledge(RetainedCloneGrant{maximum_copy_bytes:0,..grant}));assert_eq!(heap,(0,0));assert_eq!(step.progress(),RetainedCloneProgress{copied_items:1,copied_bytes:0,..Default::default()});assert!(descriptor.is_acknowledged());let(_,heap)=observed(||drop(descriptor));assert_eq!(heap,(0,0));}
  while !publication.terminal_is_empty(){let(demand,heap)=observed(||publication.retirement_demands().unwrap());assert_eq!(heap,(0,0));for denied in [Some(RetainedCloneGrant{maximum_items:0,..grant}),(demand.release_bytes>0).then_some(RetainedCloneGrant{maximum_release_bytes:demand.release_bytes.saturating_sub(1),..grant}),(demand.depth>0).then_some(RetainedCloneGrant{maximum_depth:demand.depth.saturating_sub(1),..grant})].into_iter().flatten(){let(step,heap)=observed(||publication.close_step(denied).unwrap());assert_eq!(heap,(0,0));assert_eq!(step.progress(),Default::default());assert!(!publication.terminal_is_empty());}let(step,heap)=observed(||publication.close_step(grant).unwrap());assert_physical(step.progress(),heap,grant);born+=heap.0;released+=heap.1;}
  let(step,heap)=observed(||authority.close_step(grant).unwrap());assert_physical(step.progress(),heap,grant);released+=heap.1;assert!(authority.terminal_is_empty());let mut cancellation=semio_framework_async::CancelTokenRetirement::from_token(cancel);while !cancellation.terminal_is_empty(){let(step,heap)=observed(||cancellation.close_step(RetainedCloneGrant{maximum_copy_bytes:0,..grant}).unwrap());assert_physical(step.progress(),heap,grant);released+=heap.1;}let(_,heap)=observed(||{drop(publication);drop(authority);drop(cancellation)});assert_eq!(heap,(0,0));assert_eq!(born,released);assert_eq!(source.as_ptr(),source_pointer);eprintln!("[DEBUG] actual original publication extent={extent} kind={kind:?} cancellation={cut} paidTurns={turns} copy={copied} physical={released} source={source_pointer:p} terminalDrop0 originalCopy17 originalCapacity8192");
 }}}
}
